(function(E){ const x = E["exam-09"] = E["exam-09"] || {units:{}}; (x.units = x.units || {})["x09-s"] = {"id":"x09-s","patterns":["S1-frame","S1-food","S2-object","S3-education","TR-short","PARA-discuss"],"title":{"en":"Speaking","tr":"Speaking","fa":"Speaking (صحبت کردن)"},"objective":{"en":"In this lesson you will learn to take the whole Speaking test: answer everyday questions about food with a detail, talk for two minutes about a rule you think works well, and discuss rules at school and at home with reasons and examples.","tr":"Bu derste Speaking sınavının tamamını yapmayı öğreneceksin: yemekle ilgili günlük soruları bir ayrıntıyla cevaplayacak, iyi işlediğini düşündüğün bir kural hakkında iki dakika konuşacak ve okuldaki ve evdeki kuralları nedenler ve örneklerle tartışacaksın.","fa":"در این درس یاد می‌گیری کل آزمون Speaking را انجام بدهی: به سؤال‌های روزمره درباره‌ی غذا با یک جزئیات جواب بدهی، دو دقیقه درباره‌ی قانونی که فکر می‌کنی خوب جواب می‌دهد حرف بزنی و درباره‌ی قانون‌های مدرسه و خانه با دلیل و مثال بحث کنی."},"sessions":[["explain"],["sets"],["exit"]],"explain":{"title":{"en":"Speaking: Parts 1, 2 and 3","tr":"Speaking: Part 1, 2 ve 3","fa":"Speaking: بخش‌های ۱، ۲ و ۳"},"objective":{"en":"In this lesson you will learn to take the whole Speaking test: answer everyday questions about food with a detail, talk for two minutes about a rule you think works well, and discuss rules at school and at home with reasons and examples.","tr":"Bu derste Speaking sınavının tamamını yapmayı öğreneceksin: yemekle ilgili günlük soruları bir ayrıntıyla cevaplayacak, iyi işlediğini düşündüğün bir kural hakkında iki dakika konuşacak ve okuldaki ve evdeki kuralları nedenler ve örneklerle tartışacaksın.","fa":"در این درس یاد می‌گیری کل آزمون Speaking را انجام بدهی: به سؤال‌های روزمره درباره‌ی غذا با یک جزئیات جواب بدهی، دو دقیقه درباره‌ی قانونی که فکر می‌کنی خوب جواب می‌دهد حرف بزنی و درباره‌ی قانون‌های مدرسه و خانه با دلیل و مثال بحث کنی."},"stats":[{"label":{"en":"Time","tr":"Süre","fa":"زمان"},"value":{"en":"11-14 min","tr":"11-14 dk","fa":"۱۱ تا ۱۴ دقیقه"}},{"label":{"en":"Parts","tr":"Kısım","fa":"بخش"},"value":"3"},{"label":{"en":"Part 2 talk","tr":"Part 2 konuşması","fa":"صحبت Part 2"},"value":{"en":"2 min","tr":"2 dk","fa":"۲ دقیقه"}}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: street food, a local rule, rules for children","tr":"Bu sınav: sokak yemekleri, yerel bir kural, çocuklar için kurallar","fa":"این آزمون: غذای خیابانی، یک قانون محلی، قانون‌ها برای بچه‌ها"},"intro":{"en":"Part 2 cards are not always experiences: here the card asks you to describe something, a rule. Part 3 then widens it to education and family life, which is one of the most frequent Part 3 themes.","tr":"Part 2 kartları her zaman deneyim değildir: burada kart bir şeyi, bir kuralı anlatmanı istiyor. Part 3 bunu, en sık çıkan Part 3 temalarından biri olan eğitim ve aile hayatına genişletiyor.","fa":"کارت‌های Part 2 همیشه تجربه نیستند: این‌جا کارت می‌خواهد چیزی را توصیف کنی، یک قانون. بعد Part 3 آن را به آموزش و زندگی خانوادگی گسترش می‌دهد که یکی از پرتکرارترین موضوع‌های Part 3 است."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x09-s1-ctx","exam":true,"patterns":["S1-frame","S1-food"],"often":{"pattern":"S1-food","n":7,"of":40,"label":{"en":"Comes up often in the real exam: 7 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 7’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۷ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"Part 1: you, then street food","tr":"Part 1: sen, sonra sokak yemekleri","fa":"Part 1: خودت، بعد غذای خیابانی"},"asks":{"en":"The examiner checks your name and asks about your work, studies or home, then four questions on one everyday topic. Food topics are among the most common; here it is street food.","tr":"Sınav görevlisi adını kontrol eder, işini, okulunu ya da evini sorar, sonra günlük bir konuda dört soru sorar. Yemek konuları en sık çıkanlardandır; burada konu sokak yemekleri.","fa":"ممتحن اسمت را چک می‌کند، درباره‌ی کار، درس یا خانه‌ات می‌پرسد و بعد چهار سؤال درباره‌ی یک موضوع روزمره. موضوع‌های غذا از رایج‌ترین‌هایند؛ این‌جا غذای خیابانی است."},"fields":["Work or studies","Home","Street food you like","Where and when","Hygiene and prices","Street food from other countries"],"words":[{"a":"street food","b":"food sold from stalls or vans","tr":"sokak yemeği","fa":"غذای خیابانی"},{"a":"a stall","b":"a small stand / a market table","tr":"tezgâh","fa":"دکه"},{"a":"a snack","b":"something small to eat between meals","tr":"atıştırmalık","fa":"میان‌وعده"},{"a":"on the go","b":"while walking / in a hurry","tr":"ayaküstü","fa":"سرپایی"},{"a":"tasty","b":"delicious / full of flavour","tr":"lezzetli","fa":"خوشمزه"},{"a":"hygiene","b":"how clean it is","tr":"hijyen","fa":"بهداشت"},{"a":"reasonably priced","b":"not expensive / good value","tr":"makul fiyatlı","fa":"قیمت مناسب"},{"a":"a local speciality","b":"a dish your city is known for","tr":"yöresel lezzet","fa":"غذای مخصوص محل"},{"a":"I’m not keen on","b":"I don’t really like","tr":"pek sevmem","fa":"زیاد دوست ندارم"},{"a":"now and then","b":"from time to time","tr":"arada sırada","fa":"گاهی"}],"traps":[{"en":"Answers with no detail: \"Yes, I like it.\" Say what, where or why.","tr":"Ayrıntısız cevaplar: \"Evet, severim.\" Ne, nerede ya da neden olduğunu söyle.","fa":"جواب بدون جزئیات: «بله، دوستش دارم». بگو چه، کجا یا چرا."},{"en":"A long food lecture. Two or three sentences in a natural, personal style are enough.","tr":"Uzun bir yemek dersi vermek. Doğal, kişisel üslupta iki üç cümle yeter.","fa":"سخنرانی طولانی درباره‌ی غذا. دو سه جمله‌ی طبیعی و شخصی کافی است."}],"example":{"text":"Examiner: \"Is street food popular where you live?\"","item":"Which answer is best?","answer":"Very. There’s a night market near my flat, and on Fridays it’s packed with people buying grilled corn and pancakes.","why":{"en":"An answer, a place and two specific foods, in two sentences.","tr":"İki cümlede bir cevap, bir yer ve iki somut yemek.","fa":"در دو جمله یک جواب، یک مکان و دو غذای مشخص."}}},{"id":"x09-s2-ctx","exam":true,"patterns":["S2-object"],"often":{"pattern":"S2-object","n":10,"of":40,"label":{"en":"Comes up often in the real exam: 10 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 10’unda","fa":"در آزمون واقعی زیاد می‌آید: در ۱۰ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"Part 2: a rule that works well","tr":"Part 2: iyi işleyen bir kural","fa":"Part 2: قانونی که خوب جواب می‌دهد"},"asks":{"en":"The card asks you to describe a rule in your town or city that you think works well. You say what it is, when you first noticed it and how people follow it, and explain why you think it is a good rule.","tr":"Kart, yaşadığın kasaba ya da şehirde iyi işlediğini düşündüğün bir kuralı anlatmanı istiyor. Ne olduğunu, onu ilk ne zaman fark ettiğini ve insanların ona nasıl uyduğunu söylüyor ve neden iyi bir kural olduğunu düşündüğünü açıklıyorsun.","fa":"کارت از تو می‌خواهد قانونی را در شهرت توصیف کنی که فکر می‌کنی خوب جواب می‌دهد. می‌گویی چیست، اولین بار کی متوجهش شدی و مردم چطور رعایتش می‌کنند و توضیح می‌دهی چرا به نظرت قانون خوبی است."},"fields":["What the rule is","When you noticed it","How people follow it","Why it is a good rule"],"words":[{"a":"a rule","b":"a regulation / a law / a by-law","tr":"kural","fa":"قانون"},{"a":"introduced","b":"brought in / started","tr":"getirildi","fa":"وضع شد"},{"a":"banned","b":"not allowed / prohibited","tr":"yasaklandı","fa":"ممنوع شد"},{"a":"a fine","b":"money you pay if you break a rule","tr":"para cezası","fa":"جریمه"},{"a":"follow the rule","b":"obey / stick to it","tr":"kurala uymak","fa":"قانون را رعایت کردن"},{"a":"at first","b":"in the beginning / when it started","tr":"ilk başta","fa":"اولش"},{"a":"people complained","b":"there was a lot of opposition","tr":"insanlar şikâyet etti","fa":"مردم اعتراض کردند"},{"a":"it made a difference","b":"it really changed things","tr":"fark yarattı","fa":"تفاوت ایجاد کرد"},{"a":"safer","b":"fewer accidents / less dangerous","tr":"daha güvenli","fa":"امن‌تر"},{"a":"on the whole","b":"generally / mostly","tr":"genel olarak","fa":"روی‌هم‌رفته"}],"traps":[{"en":"Talking about laws in general. The card asks about one rule in your town: name it and keep to it.","tr":"Genel olarak yasalardan söz etmek. Kart kasabandaki tek bir kuralı soruyor: adını koy ve ondan ayrılma.","fa":"حرف زدن درباره‌ی قانون‌ها به‌طور کلی. کارت درباره‌ی یک قانون در شهر توست: اسمش را بگو و از آن خارج نشو."},{"en":"A one-sentence explain line. \"Explain why you think it is a good rule\" needs reasons and a result.","tr":"Tek cümlelik açıklama satırı. \"Neden iyi bir kural olduğunu açıkla\" nedenler ve bir sonuç ister.","fa":"خط توضیحِ یک‌جمله‌ای. «توضیح بده چرا فکر می‌کنی قانون خوبی است» دلیل‌ها و یک نتیجه می‌خواهد."}],"example":{"text":"Notes (one minute): no cars outside schools 8-9 am · started 2 yrs ago · parents walk last bit · safer + quieter → kids walk more","item":"How do you start?","answer":"I’d like to talk about a rule in my town that stops cars driving past schools at the start of the school day.","why":{"en":"The first sentence names the rule and where it applies.","tr":"İlk cümle kuralın adını ve nerede geçerli olduğunu söylüyor.","fa":"جمله‌ی اول قانون و جای اجرایش را می‌گوید."}}},{"id":"x09-s3-ctx","exam":true,"patterns":["S3-education","PARA-discuss","TR-short"],"often":{"pattern":"S3-education","n":7,"of":40,"label":{"en":"Comes up often in the real exam: 7 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 7’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۷ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"Part 3: rules at school and at home","tr":"Part 3: okulda ve evde kurallar","fa":"Part 3: قانون‌ها در مدرسه و خانه"},"asks":{"en":"The examiner asks six general questions linked to the Part 2 topic: rules for children at school, and rules in families.","tr":"Sınav görevlisi Part 2 konusuyla bağlantılı altı genel soru sorar: okulda çocuklar için kurallar ve ailelerdeki kurallar.","fa":"ممتحن شش سؤال کلی مرتبط با موضوع Part 2 می‌پرسد: قانون‌های مدرسه برای بچه‌ها و قانون‌های خانواده."},"fields":["Why schools have rules","Which rules matter","Punishment","Rules at home","Parents and teenagers","Changes over time"],"words":[{"a":"discipline","b":"order / keeping control","tr":"disiplin","fa":"انضباط"},{"a":"strict","b":"firm / with many rules","tr":"katı","fa":"سخت‌گیر"},{"a":"responsibility","b":"being trusted to decide for yourself","tr":"sorumluluk","fa":"مسئولیت"},{"a":"consequences","b":"what happens if you break a rule","tr":"sonuçlar","fa":"پیامدها"},{"a":"punishment","b":"a penalty / being made to pay for a mistake","tr":"ceza","fa":"تنبیه"},{"a":"fair","b":"the same for everyone / reasonable","tr":"adil","fa":"منصفانه"},{"a":"boundaries","b":"limits that children understand","tr":"sınırlar","fa":"مرزها، حد و حدود"},{"a":"in my view","b":"I’d say / it seems to me","tr":"bence","fa":"به نظرم"},{"a":"on the other hand","b":"that said / however","tr":"öte yandan","fa":"از طرف دیگر"},{"a":"these days","b":"nowadays / compared with the past","tr":"bu günlerde","fa":"این روزها"}],"traps":[{"en":"Answering with a short personal story only. Part 3 needs a general view about people or society.","tr":"Yalnızca kısa bir kişisel hikâyeyle cevap vermek. Part 3 insanlar ya da toplum hakkında genel bir görüş ister.","fa":"جواب دادن فقط با یک ماجرای کوتاه شخصی. Part 3 نظری کلی درباره‌ی آدم‌ها یا جامعه می‌خواهد."},{"en":"Agreeing or disagreeing without a reason. Add \"because...\" and an example every time.","tr":"Neden göstermeden katılmak ya da katılmamak. Her seferinde \"because...\" ve bir örnek ekle.","fa":"موافقت یا مخالفت بدون دلیل. هر بار «because...» و یک مثال اضافه کن."}],"example":{"text":"Examiner: \"Should schools be stricter than they are now?\"","item":"What should the answer contain?","answer":"A view (in some ways, yes), a reason, an example (phones in class), and the other side (too many rules can stop students thinking for themselves).","why":{"en":"A view with reasons, an example and the other side makes a full Part 3 answer.","tr":"Nedenli bir görüş, bir örnek ve karşı taraf tam bir Part 3 cevabı oluşturur.","fa":"نظری با دلیل، یک مثال و طرف مقابل یک جواب کامل Part 3 می‌سازد."}}},{"id":"S2-things","ctx":["S2-object","S2-things"],"title":{"en":"An object, technology or a rule","tr":"Bir nesne, teknoloji ya da kural","fa":"یک شیء، یک فناوری یا یک قانون"},"asks":{"en":"A card about a thing: something you own, a luxury item, technology you stopped using, a household item, new technology, a good law, a monument. The prompts ask what it is, how you got or met it, how it is used, and why it matters.","tr":"Bir şey hakkında kart: sahip olduğun bir eşya, bir lüks eşya, kullanmayı bıraktığın bir teknoloji, bir ev eşyası, yeni bir teknoloji, iyi bir kanun, bir anıt. Maddeler ne olduğunu, nasıl edindiğini ya da tanıdığını, nasıl kullanıldığını ve neden önemli olduğunu sorar.","fa":"کارتی درباره‌ی یک چیز: وسیله‌ای که داری، یک کالای لوکس، فناوری‌ای که دیگر استفاده نمی‌کنی، یک وسیله‌ی خانه، فناوری تازه، یک قانون خوب، یک بنای یادبود. بندها می‌پرسند چیست، چطور به دستش آوردی یا با آن آشنا شدی، چطور استفاده می‌شود و چرا مهم است."},"fields":["Describe something you own that you would never give away.","Describe a piece of technology you stopped using.","Describe a useful household item.","Describe a law that you think is good.","Describe a piece of technology you find difficult to use."],"words":[{"a":"useful","b":"handy / practical","tr":"kullanışlı","fa":"به‌دردبخور"},{"a":"it works well","b":"it's reliable","tr":"güvenilir","fa":"قابل اعتماد"},{"a":"expensive","b":"it cost a fortune","tr":"bir servete mal oldu","fa":"یک عالمه پول بالایش رفت"},{"a":"I got it","b":"I was given it / I bought it second-hand","tr":"hediye aldım / ikinci el aldım","fa":"هدیه گرفتم / دست دوم خریدم"},{"a":"I use it a lot","b":"I use it on a daily basis","tr":"her gün kullanıyorum","fa":"هر روز ازش استفاده می‌کنم"},{"a":"old","b":"old-fashioned / out of date","tr":"demode","fa":"قدیمی"},{"a":"new","b":"the latest model","tr":"en son model","fa":"جدیدترین مدل"},{"a":"it broke","b":"it stopped working","tr":"bozuldu","fa":"از کار افتاد"},{"a":"easy","b":"user-friendly","tr":"kullanıcı dostu","fa":"کاربرپسند"},{"a":"hard to use","b":"complicated / fiddly","tr":"karışık, uğraştırıcı","fa":"پیچیده"},{"a":"it saves time","b":"it makes life much easier","tr":"hayatı çok kolaylaştırıyor","fa":"زندگی را خیلی راحت‌تر می‌کند"},{"a":"a rule","b":"a law / a regulation","tr":"kanun, yönetmelik","fa":"قانون"}],"traps":[{"en":"Technical descriptions are hard to keep going for two minutes. Tell a story about using it instead.","tr":"Teknik anlatımlar iki dakika sürdürülemez. Bunun yerine onu kullandığın bir anı anlat.","fa":"توضیح فنی را نمی‌شود دو دقیقه ادامه داد. به‌جایش داستان استفاده از آن را تعریف کن."},{"en":"A law or a rule card: give a real example of how it changed what people do.","tr":"Kanun ya da kural kartı: insanların davranışını nasıl değiştirdiğine gerçek bir örnek ver.","fa":"کارت قانون یا مقررات: یک مثال واقعی بزن که نشان دهد رفتار مردم را چطور عوض کرده."}],"example":{"lines":[["Candidate","The object I’d like to talk about is my grandfather’s old watch."],["Candidate","It doesn’t even keep good time any more, but I wear it on special days."],["Candidate","The reason I’d never give it away is that he wore it every day for forty years."]],"item":"Which line of the card does the last sentence answer?","answer":"The \"explain why\" line.","why":{"en":"\"The reason I’d never give it away is that...\" opens the explain part with a personal reason.","tr":"\"The reason I’d never give it away is that...\" explain kısmını kişisel bir nedenle açıyor.","fa":"«The reason I’d never give it away is that...» بخش explain را با یک دلیل شخصی باز می‌کند."}},"ideas":["when and how you got it","a time it was really useful (a short story)","what life was like before it","what you would do without it","why it matters (the \"explain\" line)"],"general":true,"patterns":["S2-object"],"often":{"pattern":"S2-object","n":10,"of":40,"label":{"en":"Comes up often in the real exam: 10 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 10’unda","fa":"در آزمون واقعی زیاد می‌آید: در ۱۰ آزمون از ۴۰ آزمونِ اخیر"}}},{"id":"S3-education","ctx":["S3-education"],"title":{"en":"Education, children and family","tr":"Eğitim, çocuklar ve aile","fa":"آموزش، کودکان و خانواده"},"asks":{"en":"General questions linked to the Part 2 card, about school rules, rewarding children, cooking at school, family gatherings, friendship and children’s books. The examiner wants an opinion, a reason, an example and, when it helps, the other side.","tr":"Part 2 kartına bağlı, okul kuralları, çocukları ödüllendirmek, okulda yemek pişirmek, aile toplantıları, arkadaşlık ve çocuk kitapları hakkında genel sorular. Sınav görevlisi bir görüş, bir neden, bir örnek ve gerektiğinde karşı tarafı ister.","fa":"سؤال‌های کلی مرتبط با کارت Part 2، درباره‌ی قانون‌های مدرسه، تشویق بچه‌ها، آشپزی در مدرسه، دورهمی‌های خانوادگی، دوستی و کتاب‌های کودکان. ممتحن یک نظر، یک دلیل، یک مثال و هرجا لازم بود طرف مقابل را می‌خواهد."},"fields":["Should children be rewarded for good behaviour?","Should schools teach cooking?","Are family gatherings less common than in the past?","Do children read less than before?","Should music and art be taught at school?"],"words":[{"a":"children","b":"youngsters / kids","tr":"çocuklar","fa":"بچه‌ها"},{"a":"parents","b":"mothers and fathers / families","tr":"ebeveynler","fa":"والدین"},{"a":"rules","b":"discipline","tr":"disiplin","fa":"انضباط"},{"a":"give a prize","b":"reward / praise","tr":"ödüllendirmek","fa":"تشویق کردن"},{"a":"punish","b":"discipline / take something away","tr":"cezalandırmak","fa":"تنبیه کردن"},{"a":"life skills","b":"practical skills like cooking","tr":"yaşam becerileri","fa":"مهارت‌های زندگی"},{"a":"creative","b":"imaginative","tr":"yaratıcı","fa":"خلاق"},{"a":"get together","b":"family gatherings","tr":"aile buluşmaları","fa":"دورهمی‌های خانوادگی"},{"a":"grow up","b":"develop / mature","tr":"büyümek, olgunlaşmak","fa":"بزرگ شدن"},{"a":"screens","b":"tablets and phones","tr":"ekranlar","fa":"صفحه‌نمایش‌ها"},{"a":"in the past","b":"when my parents were young","tr":"ebeveynlerim gençken","fa":"وقتی پدر و مادرم جوان بودند"},{"a":"nowadays","b":"these days","tr":"günümüzde","fa":"این روزها"}],"traps":[{"en":"Past-and-present questions need two tenses: \"used to\" for the past, present simple for now.","tr":"Geçmiş ve şimdi soruları iki zaman ister: geçmiş için \"used to\", şimdi için geniş zaman.","fa":"سؤال‌های گذشته و حال دو زمان می‌خواهند: «used to» برای گذشته، حال ساده برای حالا."},{"en":"Give a balanced answer when people really disagree: show you know both sides.","tr":"İnsanlar gerçekten farklı düşünüyorsa dengeli cevap ver: iki tarafı da bildiğini göster.","fa":"وقتی مردم واقعاً نظر متفاوت دارند، جواب متعادل بده: نشان بده هر دو طرف را می‌دانی."}],"example":{"lines":[["Examiner","Are family gatherings less common than they used to be?"],["Candidate","In my country, yes, a little. People used to meet every weekend at their grandparents’ house."],["Candidate","Nowadays families are often spread across different cities, so they meet mainly on holidays, although they talk online almost every day."]],"item":"How does the speaker compare past and present?","answer":"\"Used to\" for the past habit, present simple with \"nowadays\" for today, and a reason (families are spread out).","why":{"en":"Two tenses and a time word make the comparison clear.","tr":"İki zaman ve bir zaman kelimesi karşılaştırmayı netleştiriyor.","fa":"دو زمان و یک قید زمان مقایسه را روشن می‌کنند."}},"ideas":["praise works better than prizes","cooking teaches health and independence","families are busier but meet online","children read differently, not less"],"general":true,"patterns":["S3-education"],"often":{"pattern":"S3-education","n":7,"of":40,"label":{"en":"Comes up often in the real exam: 7 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 7’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۷ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Three parts, one examiner","tr":"Üç kısım, bir sınav görevlisi","fa":"سه بخش، یک ممتحن"},"body":{"en":"Part 1 (4-5 minutes): questions about you and one everyday topic. Part 2 (3-4 minutes): one minute to prepare, then up to two minutes alone, then one short question. Part 3 (4-5 minutes): a discussion of general questions. The test is recorded.","tr":"Part 1 (4-5 dakika): seninle ve günlük bir konuyla ilgili sorular. Part 2 (3-4 dakika): bir dakika hazırlık, sonra iki dakikaya kadar tek başına konuşma, sonra kısa bir soru. Part 3 (4-5 dakika): genel soruların tartışması. Sınav kaydedilir.","fa":"Part 1 (۴ تا ۵ دقیقه): سؤال‌هایی درباره‌ی خودت و یک موضوع روزمره. Part 2 (۳ تا ۴ دقیقه): یک دقیقه آماده شدن، بعد تا دو دقیقه حرف زدن به‌تنهایی و بعد یک سؤال کوتاه. Part 3 (۴ تا ۵ دقیقه): بحث درباره‌ی سؤال‌های کلی. آزمون ضبط می‌شود."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"One move for each part","tr":"Her kısım için bir hamle","fa":"برای هر بخش یک حرکت"},"steps":[{"en":"Part 1: answer, then add what, where or why. Two or three sentences.","tr":"Part 1: cevapla, sonra ne, nerede ya da neden ekle. İki üç cümle.","fa":"Part 1: جواب بده، بعد بگو چه، کجا یا چرا. دو سه جمله."},{"en":"Part 2: for an object or a rule, describe it clearly first, then tell a short story about it.","tr":"Part 2: bir nesne ya da kural için önce onu açıkça anlat, sonra onunla ilgili kısa bir hikâye anlat.","fa":"Part 2: برای یک شیء یا قانون، اول آن را روشن توصیف کن و بعد ماجرای کوتاهی درباره‌اش تعریف کن."},{"en":"Part 2: keep at least thirty seconds for the explain line, with two reasons.","tr":"Part 2: açıklama satırı için en az otuz saniye ayır, iki nedenle.","fa":"Part 2: دست‌کم سی ثانیه برای خط توضیح نگه دار، با دو دلیل."},{"en":"Part 3: a view, a reason, an example, and the other side when it helps.","tr":"Part 3: bir görüş, bir neden, bir örnek ve gerektiğinde karşı taraf.","fa":"Part 3: یک نظر، یک دلیل، یک مثال و هرجا کمک کرد طرف مقابل."}]},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Describing a rule and its effects","tr":"Bir kuralı ve etkilerini anlatmak","fa":"توصیف یک قانون و اثرهایش"},"table":{"headers":{"en":["Use","Example"],"tr":["Kullanım","Örnek"],"fa":["کاربرد","مثال"]},"rows":[["what the rule says","Cars aren’t allowed to... between 8 and 9."],["when it started","It was introduced about two years ago."],["how people reacted","At first a lot of parents complained, but..."],["the result","As a result, the streets are much safer."],["your judgement","On the whole, I think it’s one of the best decisions the council has made."]]}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"A Part 3 answer, step by step","tr":"Bir Part 3 cevabı, adım adım","fa":"یک جواب Part 3، قدم به قدم"},"instruction":"Examiner: \"Should children have to help with housework?\"","item":"Answer with four moves.","answer":"I think so, yes. Doing small jobs teaches children that a home needs everyone’s effort. In my family, for example, we each had one job, and mine was setting the table. That said, schoolwork has to come first, especially before exams.","walk":[{"en":"View: \"I think so, yes.\"","tr":"Görüş: \"I think so, yes.\"","fa":"نظر: «I think so, yes.»"},{"en":"Reason and example: it teaches shared effort; setting the table.","tr":"Neden ve örnek: ortak çabayı öğretir; sofrayı kurmak.","fa":"دلیل و مثال: مشارکت را یاد می‌دهد؛ چیدن میز."},{"en":"The other side: schoolwork comes first.","tr":"Karşı taraf: önce ders gelir.","fa":"طرف مقابل: درس اولویت دارد."}]},"quick":{"prompt":"Part 1. Examiner: \"Do you often eat street food?\" Which answer is best?","options":["Yes.","Street food has a very long history and is popular in many countries around the world.","Now and then, mostly at weekends. There’s a stall near the station that does amazing falafel."],"correct":2,"why":{"en":"An answer with a time and a specific example. \"Yes.\" is too short; the answer about history does not talk about you.","tr":"Bir zaman ve somut bir örnekle cevap. \"Yes.\" çok kısa; tarihle ilgili cevap senden söz etmiyor.","fa":"جوابی با زمان و یک مثال مشخص. «Yes.» خیلی کوتاه است؛ جوابِ تاریخچه درباره‌ی خودت نیست."}},"remember":{"en":"Part 1 personal details, Part 2 describe then explain, Part 3 people in general with reasons.","tr":"Part 1 kişisel ayrıntılar, Part 2 önce anlat sonra açıkla, Part 3 nedenleriyle genel olarak insanlar.","fa":"Part 1 جزئیات شخصی، Part 2 اول توصیف بعد توضیح، Part 3 آدم‌ها به‌طور کلی با دلیل."},"type":"explain","id":"c-x09-s-e","course":"ielts-exams","exam":"exam-09","unit":"x09-s"},"sets":{"title":{"en":"The Speaking test","tr":"Speaking sınavı","fa":"آزمون Speaking"},"note":{"en":"Do the three parts in order, without a break, as in the real test. Record yourself if you can, then use the self-check under each part.","tr":"Gerçek sınavdaki gibi üç kısmı sırayla ve ara vermeden yap. Yapabilirsen kendini kaydet, sonra her kısmın altındaki öz değerlendirmeyi kullan.","fa":"سه بخش را به ترتیب و بدون مکث انجام بده، مثل آزمون واقعی. اگر می‌توانی صدایت را ضبط کن و بعد از خودارزیابیِ زیر هر بخش استفاده کن."},"sequential":true,"examinerVoice":{"accent":"British (standard Southern)","gender":"M","tts":{"engine":"kokoro","voice":"bm_lewis"},"role":"Examiner"},"sets":[{"part":"Part 1","ctx":["S1-frame","S1-food"],"minutes":[4,5],"title":{"en":"Part 1: about you, then street food","tr":"Part 1: senin hakkında, sonra sokak yemekleri","fa":"Part 1: درباره‌ی خودت، بعد غذای خیابانی"},"examinerIntro":["Good morning. My name is Robert Kemp. Can you tell me your full name, please?","Thank you. And can I see your identification, please?","Thank you. Now, in this first part, I’d like to ask you some questions about yourself."],"frame":["Let’s talk about your home. Do you live in a house or a flat?","Which room do you spend the most time in?","Would you like to move somewhere else in the future?"],"topicIntro":"Now let’s talk about street food.","questions":["Is street food popular where you live?","What kind of street food do you like best?","Do you think street food is healthy? [Why/Why not?]","Have you ever tried street food from another country?"],"model":"Q: Is street food popular where you live?\nA: Very. There’s a night market near my flat, and on Friday evenings it’s packed with people buying grilled corn and pancakes.\n\nQ: What kind of street food do you like best?\nA: Anything spicy, really, but my favourite is a kind of flatbread filled with potatoes and herbs. The stall I go to cooks it right in front of you.\n\nQ: Do you think street food is healthy?\nA: Some of it is, actually. A lot of it is fried, of course, but many stalls use fresh vegetables, and the portions are smaller than in restaurants.\n\nQ: Have you ever tried street food from another country?\nA: Yes, when I visited Vietnam a few years ago. I had noodle soup for breakfast on a tiny plastic stool, and it was one of the best meals of the trip.","moves":[{"label":{"en":"Answer first","tr":"Önce cevap","fa":"اول جواب"},"example":"Very."},{"label":{"en":"Add where, what or why","tr":"Nerede, ne ya da neden ekle","fa":"بگو کجا، چه یا چرا"},"example":"There’s a night market near my flat, and on Friday evenings it’s packed."},{"label":{"en":"A small story when the question invites it","tr":"Soru uygunsa küçük bir hikâye","fa":"وقتی سؤال اجازه می‌دهد یک ماجرای کوتاه"},"example":"I had noodle soup for breakfast on a tiny plastic stool."}],"selfCheck":[{"en":"I answered every question with two or three sentences.","tr":"Her soruyu iki üç cümleyle cevapladım.","fa":"به هر سؤال با دو سه جمله جواب دادم."},{"en":"I named specific foods and places, not just \"food\".","tr":"Yalnızca \"yemek\" değil, belirli yemekler ve yerler söyledim.","fa":"غذاها و جاهای مشخص را اسم بردم، نه فقط «غذا»."},{"en":"I used the past simple for the question about a past experience.","tr":"Geçmiş bir deneyimle ilgili soruda past simple kullandım.","fa":"برای سؤال درباره‌ی تجربه‌ی گذشته از گذشته‌ی ساده استفاده کردم."}]},{"part":"Part 2","ctx":["S2-object"],"minutes":[3,4],"title":{"en":"Part 2: a rule that works well","tr":"Part 2: iyi işleyen bir kural","fa":"Part 2: قانونی که خوب جواب می‌دهد"},"examinerIntro":["Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. Before you talk, you’ll have one minute to think about what you’re going to say. You can make some notes if you wish. Do you understand?","Here’s some paper and a pencil for making notes, and here’s your topic. I’d like you to describe a rule in your town or city that you think works well.","All right? Remember you have one to two minutes for this. Don’t worry if I stop you. I’ll tell you when the time is up. Can you start speaking now, please?"],"card":{"task":"Describe a rule in your town or city that you think works well.","bullets":["what the rule is","when you first noticed it","how people follow it","and explain why you think it is a good rule"]},"prep":60,"talk":120,"roundingOff":["Are there any rules in your town that you would like to change?"],"model":"I’d like to talk about a rule in my town that stops cars from driving along the streets right outside primary schools at the beginning and end of the school day.\n\nIt was introduced about two years ago. I first noticed it because I cycle past a school on my way to work, and one morning there were barriers across the road and a sign saying that only bicycles and pedestrians could use it between eight and nine.\n\nAt first, quite a few parents complained. They were used to driving right up to the gate, and some said it would make them late for work. But the council kept the rule, and now most families park a few streets away and walk the last five minutes, or the children cycle. If someone drives in, there’s a fine, although I’ve never seen anyone try.\n\nSo why do I think it’s a good rule? Firstly, it’s made the streets much safer. Before, there were cars reversing and stopping everywhere, with small children running between them. Secondly, it has changed people’s habits. More children walk or cycle to school now, which is good for their health, and the air outside the school is noticeably cleaner. And honestly, the whole street feels calmer in the morning. I think it shows that a small, simple rule can make a real difference if the council is brave enough to stick with it.","moves":[{"label":{"en":"Name the rule clearly","tr":"Kuralı açıkça söyle","fa":"قانون را روشن بگو"},"example":"A rule in my town that stops cars from driving along the streets right outside primary schools."},{"label":{"en":"Tell how it started and how people reacted","tr":"Nasıl başladığını ve insanların tepkisini anlat","fa":"بگو چطور شروع شد و مردم چه واکنشی نشان دادند"},"example":"At first, quite a few parents complained... now most families park a few streets away."},{"label":{"en":"Give two reasons in the explain line","tr":"Açıklama satırında iki neden ver","fa":"در خط توضیح دو دلیل بیاور"},"example":"Firstly, it’s made the streets much safer... Secondly, it has changed people’s habits."}],"selfCheck":[{"en":"I covered all four lines of the card and spoke for close to two minutes.","tr":"Kartın dört satırının hepsini ele aldım ve iki dakikaya yakın konuştum.","fa":"هر چهار خط کارت را گفتم و نزدیک دو دقیقه حرف زدم."},{"en":"I described one rule, not rules in general.","tr":"Genel olarak kuralları değil, tek bir kuralı anlattım.","fa":"یک قانون را توصیف کردم، نه قانون‌ها به‌طور کلی."},{"en":"I gave at least two reasons, linked with firstly, secondly, and.","tr":"En az iki neden verdim ve onları firstly, secondly, and ile bağladım.","fa":"دست‌کم دو دلیل آوردم و با firstly، secondly و and به هم وصلشان کردم."}]},{"part":"Part 3","ctx":["S3-education"],"minutes":[4,5],"title":{"en":"Part 3: rules at school and at home","tr":"Part 3: okulda ve evde kurallar","fa":"Part 3: قانون‌ها در مدرسه و خانه"},"examinerIntro":["We’ve been talking about a rule that works well, and I’d like to discuss with you one or two more general questions related to this."],"subtopics":[{"title":"Rules at school","questions":["Why do schools need rules?","Which school rules do you think are the most important?","What should happen when students break school rules?"]},{"title":"Rules at home","questions":["What kinds of rules do parents usually have for their children?","Should teenagers be allowed to make their own rules at home?","Are families today stricter or less strict than in the past?"]}],"model":"Q: What should happen when students break school rules?\nA: I think it depends on the rule and on why it was broken. For small things, like being late, a conversation is usually more useful than a punishment, because the teacher can find out if there’s a problem at home. For serious things, like bullying, there do need to be clear consequences, so that other students feel protected. What matters most, in my view, is that the system is fair and the same for everyone.\n\nQ: Are families today stricter or less strict than in the past?\nA: In most ways, less strict, I’d say. My grandparents weren’t allowed to question their parents at all, whereas children today are encouraged to give their opinions. On the other hand, parents now worry more about things like screen time and safety, so in those areas they can actually be stricter than earlier generations.","moves":[{"label":{"en":"Give a clear view","tr":"Net bir görüş ver","fa":"نظرت را روشن بگو"},"example":"In most ways, less strict, I’d say."},{"label":{"en":"Support it: reason + example","tr":"Destekle: neden + örnek","fa":"پشتیبانی کن: دلیل + مثال"},"example":"My grandparents weren’t allowed to question their parents at all, whereas children today are encouraged to give their opinions."},{"label":{"en":"Show the other side","tr":"Karşı tarafı göster","fa":"طرف مقابل را نشان بده"},"example":"On the other hand, parents now worry more about things like screen time..."}],"selfCheck":[{"en":"I gave a clear view in my first sentence.","tr":"İlk cümlemde net bir görüş verdim.","fa":"در جمله‌ی اولم نظر روشنی دادم."},{"en":"I compared the past and the present where the question asked.","tr":"Sorunun istediği yerde geçmişi ve bugünü karşılaştırdım.","fa":"هرجا سؤال خواست گذشته و حال را مقایسه کردم."},{"en":"I talked about people in general, not only about myself.","tr":"Yalnızca kendimden değil, genel olarak insanlardan söz ettim.","fa":"درباره‌ی آدم‌ها به‌طور کلی حرف زدم، نه فقط خودم."}]}],"type":"sets","id":"c-x09-s-p","course":"ielts-exams","exam":"exam-09","unit":"x09-s"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"\"The rule was introduced two years ago.\" Introduced means...","options":["cancelled","started for the first time","explained"],"correct":1,"why":{"en":"To introduce a rule = to bring it in.","tr":"Bir kural introduce etmek = onu yürürlüğe koymak.","fa":"introduce کردن یک قانون یعنی وضع کردنش."}},{"tests":"paraphrase","point":3,"prompt":"Which phrase means \"to obey a rule\"?","options":["to stick to it","to break it","to complain about it"],"correct":0,"why":{"en":"Stick to a rule = follow it.","tr":"Stick to a rule = ona uymak.","fa":"stick to a rule یعنی رعایتش کردن."}},{"tests":"method","point":2,"prompt":"The Part 2 card asks you to describe a rule. How should you begin?","options":["Talk about laws in your country in general","Start with why it is good","Name the rule and where it applies"],"correct":2,"why":{"en":"Describe the thing clearly first; the reasons come at the end.","tr":"Önce şeyi açıkça anlat; nedenler sonda gelir.","fa":"اول خودِ آن را روشن توصیف کن؛ دلیل‌ها آخر می‌آیند."}},{"tests":"trap","point":2,"prompt":"Part 3: \"Why do schools need rules?\" A candidate says: \"My school had a lot of rules.\" What is missing?","options":["A longer story about the school","A general reason, with an example","Nothing"],"correct":1,"why":{"en":"Part 3 asks why, in general; a personal fact does not answer it.","tr":"Part 3 genel olarak nedenini sorar; kişisel bir bilgi soruyu cevaplamaz.","fa":"Part 3 به‌طور کلی می‌پرسد چرا؛ یک واقعیت شخصی جوابش نیست."}},{"tests":"method","point":2,"prompt":"Which sentence shows the other side in Part 3?","options":["On the other hand, too many rules can stop students thinking for themselves.","I agree completely.","My teacher was very strict."],"correct":0,"why":{"en":"\"On the other hand\" introduces a balancing point.","tr":"\"On the other hand\" dengeleyici bir noktayı getirir.","fa":"«on the other hand» نکته‌ی متعادل‌کننده را می‌آورد."}}],"id":"c-x09-s-x","course":"ielts-exams","exam":"exam-09","unit":"x09-s"}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
